/* resourceConfig is generated by the build. The key is intentionally public. */
const bytes = value => Uint8Array.from(atob(value), character => character.charCodeAt(0))
const resourceKey = crypto.subtle.importKey('raw', bytes(resourceConfig.key), 'AES-GCM', false, ['decrypt'])
self.addEventListener('install', event => event.waitUntil(self.skipWaiting()))
self.addEventListener('activate', event => event.waitUntil(self.clients.claim()))
self.addEventListener('message', event => {
  if (event.data?.type !== 'resource-claim') return
  event.waitUntil(self.clients.claim().then(() => event.ports[0]?.postMessage({ version: resourceConfig.version })))
})

async function decryptResource(request, asset) {
  const response = await fetch(new URL(asset.file, self.registration.scope))
  if (!response.ok) return new Response('Encrypted resource unavailable', { status: response.status })
  const plaintext = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: bytes(asset.iv) }, await resourceKey, await response.arrayBuffer())
  const headers = { 'Content-Type': asset.type, 'Cache-Control': 'no-store', 'Accept-Ranges': 'bytes' }
  const range = request.headers.get('Range')
  if (range) {
    const match = /^bytes=(\d*)-(\d*)$/.exec(range)
    if (!match || (!match[1] && !match[2])) return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${plaintext.byteLength}` } })
    const size = plaintext.byteLength
    const start = match[1] ? Number(match[1]) : Math.max(0, size - Number(match[2]))
    const end = match[1] && match[2] ? Math.min(Number(match[2]), size - 1) : size - 1
    if (start >= size || end < start) return new Response(null, { status: 416, headers: { 'Content-Range': `bytes */${size}` } })
    headers['Content-Range'] = `bytes ${start}-${end}/${size}`
    headers['Content-Length'] = String(end - start + 1)
    return new Response(plaintext.slice(start, end + 1), { status: 206, headers })
  }
  headers['Content-Length'] = String(plaintext.byteLength)
  return new Response(plaintext, { headers })
}
async function pageResponse(request, relative) {
  let filename = relative || 'index.html'
  if (filename.endsWith('/')) filename += 'index.html'
  else if (!filename.split('/').pop().includes('.')) filename += '.html'
  if (!filename.endsWith('.html')) return fetch(request)
  const page = resourceConfig.pages[filename.toLowerCase()]
  if (!page) return fetch(request)
  const response = await fetch(new URL(page, self.registration.scope), { cache: 'no-cache' })
  if (!response.ok) return fetch(request)
  const headers = new Headers(response.headers)
  headers.set('Content-Type', 'text/html; charset=utf-8')
  return new Response(response.body, { status: response.status, headers })
}
self.addEventListener('fetch', event => {
  const url = new URL(event.request.url)
  if (event.request.method !== 'GET' || url.origin !== self.location.origin || !url.pathname.startsWith(resourceConfig.base)) return
  let relative
  try { relative = decodeURIComponent(url.pathname.slice(resourceConfig.base.length)) } catch { return }
  const asset = resourceConfig.assets[relative]
  if (asset) {
    event.respondWith(decryptResource(event.request, asset).catch(() => new Response('Resource decryption failed', { status: 502 })))
  } else if (event.request.mode === 'navigate') {
    event.respondWith(pageResponse(event.request, relative))
  }
})
